import os
import stat

def scan_directory(path):
    """扫描目录查找权限异常"""
    print(f"[audit-perms] 扫描 {path}...")
    anomalies = []

    try:
        for entry in os.listdir(path):
            fullpath = os.path.join(path, entry)
            if entry.startswith('.'):
                continue

            try:
                st = os.stat(fullpath)
                mode = st.st_mode

                # 检查 SUID
                if mode & stat.S_ISUID:
                    anomalies.append(f"[WARN] SUID: {fullpath} (mode {oct(mode & 0o7777)})")

                # 检查世界可写
                if mode & stat.S_IWOTH:
                    anomalies.append(f"[WARN] world-writable: {fullpath} (mode {oct(mode & 0o7777)})")

            except (OSError, IOError) as e:
                print(f"[ERROR] 无法访问 {fullpath}: {e}")

    except (OSError, IOError) as e:
        print(f"[ERROR] 无法打开目录 {path}: {e}")

    return anomalies

