#!/usr/bin/env python3
"""
DNS Resolver 检查脚本
用于 DNS cutover 期间的快速探测
"""

import socket
import subprocess
import json
import time
from datetime import datetime

def check_dns_resolution(hostname, record_type="A"):
    """检查 DNS 解析"""
    try:
        # 使用 Python socket 进行 DNS 查询
        ip = socket.gethostbyname(hostname)
        return {
            "status": "success",
            "ip": ip,
            "method": "socket"
        }
    except socket.gaierror as e:
        return {
            "status": "failed",
            "error": str(e),
            "method": "socket"
        }

def check_with_nslookup(hostname):
    """使用 nslookup 检查"""
    try:
        result = subprocess.run(
            ["nslookup", hostname],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0:
            return {
                "status": "success",
                "method": "nslookup",
                "output": result.stdout[:200]
            }
        return {
            "status": "failed",
            "error": result.stderr,
            "method": "nslookup"
        }
    except Exception as e:
        return {
            "status": "failed",
            "error": str(e),
            "method": "nslookup"
        }

def check_with_dig(hostname):
    """使用 dig 检查"""
    try:
        result = subprocess.run(
            ["dig", "+short", hostname],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0:
            return {
                "status": "success",
                "ip": result.stdout.strip(),
                "method": "dig"
            }
        return {
            "status": "failed",
            "error": result.stderr,
            "method": "dig"
        }
    except Exception as e:
        return {
            "status": "failed",
            "error": str(e),
            "method": "dig"
        }

def check_with_host(hostname):
    """使用 host 命令检查"""
    try:
        result = subprocess.run(
            ["host", hostname],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0:
            return {
                "status": "success",
                "method": "host",
                "output": result.stdout[:200]
            }
        return {
            "status": "failed",
            "error": result.stderr,
            "method": "host"
        }
    except Exception as e:
        return {
            "status": "failed",
            "error": str(e),
            "method": "host"
        }

def check_dns_server(hostname):
    """检查 DNS 服务器响应"""
    try:
        result = subprocess.run(
            ["nslookup", "-query=@", hostname],
