from flask import Flask, jsonify, request
import os
import socket
import subprocess

app = Flask(__name__)

@app.route("/health")
def health():
    return jsonify(status="ok")

@app.route("/api/users")
def get_users():
    db_url = os.environ.get("DATABASE_URL", "sqlite:///data/app.db")
    return jsonify(users=["alice", "bob"])

@app.route("/debug/connect")
def debug_connect():
    """Establish remote debug connection"""
    remote_host = os.environ.get("REMOTE_HOST", "localhost")
    remote_port = os.environ.get("REMOTE_PORT", "22")
    debug_port = os.environ.get("DEBUG_PORT", "5678")

    try:
        # Test connection to remote debug port
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5)
        sock.connect((remote_host, int(debug_port)))
        sock.close()
        return jsonify(status="connected", host=remote_host, port=debug_port)
    except Exception as e:
        return jsonify(status="disconnected", error=str(e))

@app.route("/debug/status")
def debug_status():
    """Check remote debug status"""
    return jsonify(
        status="running",
        remote_host=os.environ.get("REMOTE_HOST", "localhost"),
        local_port=os.environ.get("LOCAL_PORT", "9090"),
        debug_port=os.environ.get("DEBUG_PORT", "5678")
    )

if __name__ == "__main__":
    host = os.environ.get("FLASK_HOST", "0.0.0.0")
    port = int(os.environ.get("FLASK_PORT", "8080"))
    app.run(host=host, port=port)
EOF

